// Module fraud, key: the order id. Owns R2.1 (the verdict of fraud.check), R2.2 (the review task, its single deadline,
// the answers that count, the timeout) and S3 (one review deadline per order, from the first review task).
// Effects: fraud.check (key 'check'). Human tasks: fraudReview ('review-<n>'). Wake-up: 'deadline', after the
// deadline and never at it (an answer exactly at the deadline still counts). Always returns `output`.

const MIN = 60000;

function lastSunday(y, m) {
  const last = new Date(Date.UTC(y, m + 1, 0));
  return last.getUTCDate() - last.getUTCDay();
}

// Europe/Amsterdam offset in minutes at an instant (EU rule, switching at 01:00 UTC on the last Sundays of March and
// October).
function amsOffsetMin(ms) {
  const y = new Date(ms).getUTCFullYear();
  const start = Date.UTC(y, 2, lastSunday(y, 2), 1);
  const end = Date.UTC(y, 9, lastSunday(y, 9), 1);
  return ms >= start && ms < end ? 120 : 60;
}

function amsIso(ms) {
  const off = amsOffsetMin(ms);
  const d = new Date(ms + off * MIN);
  const p = n => String(n).padStart(2, '0');
  return `${d.getUTCFullYear()}-${p(d.getUTCMonth() + 1)}-${p(d.getUTCDate())}T${p(d.getUTCHours())}:${p(d.getUTCMinutes())}:${p(d.getUTCSeconds())}+${p(Math.floor(off / 60))}:${p(off % 60)}`;
}

function readJson(files, path) {
  let v = files?.[path];
  if (v === undefined) { v = files; for (const seg of path.split('/')) v = v?.[seg]; }
  if (typeof v === 'string') return JSON.parse(v);
  return v ?? null;
}

function policyParam(files, edition, name) {
  const p = readJson(files, `rulebook/${edition}/policy.json`) ?? {};
  const v = p[name] ?? p.policy?.[name];
  if (typeof v !== 'number') throw new Error(`policy ${edition} has no ${name}`);
  return v;
}

function outOf(st) {
  return {
    output: {
      state: st?.state ?? 'idle',
      at: st?.at ?? null,
      reason: st?.reason ?? null,
      busy: !!st && !!st.checkInFlight,
    },
  };
}

export function step(input, ctx) {
  switch (input.op) {
    case 'start': return start(input, ctx);
    case 'stop': return stop(input, ctx);
    case 'resume': return resume(input, ctx);
  }
  throw new Error(`fraud: unknown op ${input.op}`);
}

export function onEvent(event, ctx) {
  const st = ctx.state;
  if (!st) return outOf(null);
  const p = event.payload ?? {};
  const now = ctx.now;

  if (event.type === 'effect.result' && p.key === 'check') {
    if (st.state !== 'checking') return { ...outOf({ ...st, checkInFlight: false }), state: { ...st, checkInFlight: false } };
    const body = p.result ?? p;
    const verdict = p.status === 'ok' ? (body.verdict ?? p.verdict) : undefined;
    const next = { ...st, checkInFlight: false };
    if (verdict !== 'pass' && verdict !== 'reject' && verdict !== 'review') {
      // an error, or no verdict in the answer: read again (a read has no effect), at most three times
      if ((st.checks ?? 1) >= 3) return { ...outOf(next), state: next };
      const again = { ...next, checks: (st.checks ?? 1) + 1, checkInFlight: true };
      return { ...outOf(again), state: again, effects: [checkEffect(st.orderId)] };
    }
    if (verdict === 'pass') return decide({ ...next, state: 'cleared', at: st.placedAt }, null);
    if (verdict === 'reject') return decide({ ...next, state: 'cancel', at: now, reason: 'fraud' }, null);
    // review (R2.2): one task, the deadline fixed from its creation
    const deadline = amsIso(Date.parse(now) + policyParam(ctx.files, st.edition, 'fraudReviewHours') * 60 * MIN);
    const n2 = { ...next, state: 'review', deadline, tasks: 1 };
    return { ...outOf(n2), state: n2, humanTasks: [reviewTask(st.orderId, 1, deadline)], obligations: deadlineWakeUp(deadline) };
  }

  if (st.state !== 'review') return outOf(st);
  const deadlineMs = Date.parse(st.deadline);

  if (event.type === 'humanTask.answered') {
    const a = Date.parse(event.at ?? now);
    if (a > deadlineMs) return outOf(st);                               // late answers change nothing
    const decision = (p.answer ?? p).decision;
    if (decision === 'approve') return decide({ ...st, state: 'cleared', at: event.at }, { cancel: ['deadline'] });
    if (decision === 'reject') return decide({ ...st, state: 'cancel', at: event.at, reason: 'fraud' }, { cancel: ['deadline'] });
    return askAgain(st, now);                                           // unusable: ask again, same deadline (R2.2)
  }
  if (event.type === 'humanTask.answerRejected' || event.type === 'humanTask.withdrawn') return askAgain(st, now);
  if (event.type === 'timer.fired' && p.obligationId === 'deadline') {
    // No usable answer by the deadline: cancel after it (R2.2).
    return decide({ ...st, state: 'cancel', at: now, reason: 'fraud-review-timeout' }, null);
  }
  return outOf(st);
}

function decide(st, obligations) {
  const next = { ...st, checkInFlight: false };
  return { ...outOf(next), state: next, ...(obligations ? { obligations: { ...obligations } } : {}) };
}

function askAgain(st, now) {
  if (Date.parse(now) > Date.parse(st.deadline)) return outOf(st);      // the deadline does not move (R2.2, S3)
  const tasks = st.tasks + 1;
  const next = { ...st, tasks };
  return { ...outOf(next), state: next, humanTasks: [reviewTask(st.orderId, tasks, st.deadline)] };
}

function reviewTask(orderId, n, deadline) {
  return {
    id: `review-${n}`,
    kind: 'fraudReview',
    role: 'fraudAnalyst',
    subject: orderId,
    question: `Review order ${orderId} for fraud and answer approve or reject.`,
    answerSchema: {
      type: 'object',
      required: ['decision'],
      additionalProperties: false,
      properties: { decision: { enum: ['approve', 'reject'] } },
    },
    dueAt: deadline,
    onTimeout: 'none',
  };
}

function deadlineWakeUp(deadline) {
  // one minute after the deadline is too early for a late-delivered answer; an hour is still inside (deadline, +120 min]
  return { upsert: [{ id: 'deadline', kind: 'deadline', anchor: 'review', dueAt: amsIso(Date.parse(deadline) + 60 * MIN), onDue: 'deadline' }] };
}

function checkEffect(orderId) {
  return { key: 'check', system: 'fraud', op: 'check', args: { orderId } };
}

function start(input, ctx) {
  // R2.1: read the verdict once.
  if (ctx.state) return outOf(ctx.state);
  const st = { orderId: input.orderId, placedAt: input.placedAt, edition: input.edition, state: 'checking', at: null, reason: null, deadline: null, tasks: 0, checks: 1, checkInFlight: true };
  return { ...outOf(st), state: st, effects: [checkEffect(input.orderId)] };
}

function stop(input, ctx) {
  // R6.4: a cancel before clearing counts; the review is closed and a later answer changes nothing.
  const st = ctx.state;
  if (!st || st.state === 'cleared' || st.state === 'cancel') return outOf(st);
  const next = { ...st, state: 'stopped', at: input.at ?? null, reason: null };
  return { ...outOf(next), state: next, obligations: { cancel: ['deadline'] } };
}

function resume(input, ctx) {
  // §3.5: a migrated order: its verdict and open review task come from the records.
  const r = input.records?.fraud;
  if (!r) return outOf(null);
  const st = { orderId: ctx.key, placedAt: r.placedAt, edition: r.edition, state: r.state, at: r.at ?? null, reason: r.reason ?? null,
    deadline: r.deadline ?? null, tasks: r.tasks ?? 0, checkInFlight: false };
  return { ...outOf(st), state: st };
}
// Module customer-action, key: the order id. Owns R3.1 (action-required within 120 min of clearing), R3.2 (the
// customer's deadline D = placedAt + customerActionHours, the first amend or cancel at or before D counts, the timeout
// after D) and S1 (D is anchored at placedAt, inclusive for the customer, exclusive for the timeout).
// Calls statuses and notices only. Wake-up 'deadline' is set after D (D + 1 min), never at D. Always returns `output`.

const MIN = 60000;

function lastSunday(y, m) {
  const last = new Date(Date.UTC(y, m + 1, 0));
  return last.getUTCDate() - last.getUTCDay();
}

// Europe/Amsterdam offset in minutes at an instant (EU rule: DST from the last Sunday of March to the last Sunday of
// October, at 01:00 UTC).
function amsOffsetMin(ms) {
  const y = new Date(ms).getUTCFullYear();
  const start = Date.UTC(y, 2, lastSunday(y, 2), 1);
  const end = Date.UTC(y, 9, lastSunday(y, 9), 1);
  return ms >= start && ms < end ? 120 : 60;
}

function amsIso(ms) {
  const off = amsOffsetMin(ms);
  const d = new Date(ms + off * MIN);
  const p = n => String(n).padStart(2, '0');
  return `${d.getUTCFullYear()}-${p(d.getUTCMonth() + 1)}-${p(d.getUTCDate())}T${p(d.getUTCHours())}:${p(d.getUTCMinutes())}:${p(d.getUTCSeconds())}+${p(Math.floor(off / 60))}:${p(off % 60)}`;
}

function readJson(files, path) {
  let v = files?.[path];
  if (v === undefined) { v = files; for (const seg of path.split('/')) v = v?.[seg]; }
  if (typeof v === 'string') return JSON.parse(v);
  return v ?? null;
}

function policyParam(files, edition, name) {
  const p = readJson(files, `rulebook/${edition}/policy.json`) ?? {};
  const v = p[name] ?? p.policy?.[name];
  if (typeof v !== 'number') throw new Error(`policy ${edition} has no ${name}`);
  return v;
}

function outOf(st) {
  return { output: { state: st?.state ?? 'idle', at: st?.at ?? null, reason: st?.reason ?? null, busy: false } };
}

export function step(input, ctx) {
  switch (input.op) {
    case 'start': return start(input, ctx);
    case 'advance': return advance(input, ctx);
    case 'action': return action(input, ctx);
    case 'resume': return resume(input, ctx);
  }
  throw new Error(`customer-action: unknown op ${input.op}`);
}

export function onEvent(event, ctx) {
  const st = ctx.state;
  const fired = event.type === 'timer.fired' && event.payload?.obligationId === 'deadline';
  if (!st || st.state !== 'waiting' || !fired) return outOf(st);
  // Nothing counted by D: every fulfilment cancelled, the order timedOut, one notice (R3.2).
  for (const f of st.fulfilments) ctx.call('statuses', ctx.key, { op: 'set', fulfilmentId: f.fulfilmentId, status: 'cancelled' });
  ctx.call('statuses', ctx.key, { op: 'set', fulfilmentId: null, status: 'timedOut' });
  ctx.call('notices', ctx.key, { op: 'send', template: 'order-timed-out', about: ctx.key });
  const next = { ...st, state: 'timedOut', at: amsIso(event.at ? Date.parse(event.at) : Date.parse(ctx.now)) };
  return { ...outOf(next), state: next };
}

function start(input, ctx) {
  // D from placedAt, the edition in force at placedAt (R3.2, S1). The wake-up is one minute after D.
  if (ctx.state) return outOf(ctx.state);
  const hours = policyParam(ctx.files, input.edition, 'customerActionHours');
  const D = Date.parse(input.placedAt) + hours * 60 * MIN;
  const st = { state: 'waiting', D: amsIso(D), clearedAt: input.clearedAt, advanced: false, fulfilments: input.fulfilments, at: null, reason: null };
  return {
    ...outOf(st),
    state: st,
    obligations: { upsert: [{ id: 'deadline', kind: 'deadline', anchor: 'D', dueAt: amsIso(D + MIN), onDue: 'deadline' }] },
  };
}

function advance(input, ctx) {
  // R3.1: the order customerActionRequired and the action-required notice, once, while the customer has not acted.
  const st = ctx.state;
  if (!st || st.state !== 'waiting' || st.advanced) return outOf(st);
  ctx.call('statuses', ctx.key, { op: 'set', fulfilmentId: null, status: 'customerActionRequired' });
  ctx.call('notices', ctx.key, { op: 'send', template: 'action-required', about: ctx.key });
  const next = { ...st, advanced: true };
  return { ...outOf(next), state: next };
}

function action(input, ctx) {
  // The first amend or cancel at or before D counts (D itself counts, S1). Later actions change nothing.
  const st = ctx.state;
  if (!st || st.state !== 'waiting') return outOf(st);
  if (Date.parse(input.at) > Date.parse(st.D)) return outOf(st);
  const cancelTimer = { cancel: ['deadline'] };
  if (input.action === 'cancel') {
    const next = { ...st, state: 'cancel', reason: 'customer', at: input.at };
    return { ...outOf(next), state: next, obligations: cancelTimer };
  }
  // amend (R3.2): every unavailable fulfilment cancelled; the rest continue, ready at the amend's time.
  for (const f of st.fulfilments) {
    if (!f.available) ctx.call('statuses', ctx.key, { op: 'set', fulfilmentId: f.fulfilmentId, status: 'cancelled' });
  }
  const anyAvailable = st.fulfilments.some(f => f.available);
  const next = anyAvailable
    ? { ...st, state: 'ready', at: input.at, reason: null }
    : { ...st, state: 'cancel', at: input.at, reason: 'nothing-available' };
  return { ...outOf(next), state: next, obligations: cancelTimer };
}

function resume(input, ctx) {
  // §3.5: a migrated order that is still waiting for its customer keeps its deadline (the wake-up is re-set).
  const r = input.records?.customerAction;
  if (!r) return outOf(null);
  const st = { state: r.state, D: r.D, clearedAt: r.clearedAt, advanced: true, fulfilments: r.fulfilments, at: r.at ?? null, reason: r.reason ?? null };
  if (st.state !== 'waiting') return { ...outOf(st), state: st };
  return {
    ...outOf(st),
    state: st,
    obligations: { upsert: [{ id: 'deadline', kind: 'deadline', anchor: 'D', dueAt: amsIso(Math.max(Date.parse(st.D) + MIN, Date.parse(ctx.now) + MIN)), onDue: 'deadline' }] },
  };
}
// Module notices, key: the order id. The only sender of notify.send. Owns §4.8 (each required notice exactly once,
// `to` is the customer's email, `about` the order id or, for fulfilment-failed, the fulfilment id).
// Local keys: '<template>.<about>' and 'cancel-refused.<occurrence>'. Always returns `output`.

const TEXT = {
  'action-required': 'Some items of your order are not available. Please amend or cancel the order before the deadline.',
  'order-cancelled': 'Your order has been cancelled.',
  'order-timed-out': 'Your order was not confirmed in time and has been closed.',
  'fulfilment-failed': 'Part of your order could not be fulfilled and has been reversed.',
  'cancel-refused': 'Your order has already been collected and can no longer be cancelled.',
  'unknown-order': 'We could not find an order with that reference.',
};

function readJson(files, path) {
  let v = files?.[path];
  if (v === undefined) { v = files; for (const seg of path.split('/')) v = v?.[seg]; }
  if (typeof v === 'string') return JSON.parse(v);
  return v ?? null;
}

// The API may rename a field during the run; api/<system>.schema.json in ctx.files always shows the current names
// (SPEC-E §4.2). An argument the current schema no longer names moves to the single property that replaces it.
function fit(system, op, args, ctx) {
  const schema = readJson(ctx.files, `api/${system}.schema.json`);
  const a = schema?.ops?.[op]?.args;
  if (!a || !a.properties || !args) return args;
  const props = Object.keys(a.properties);
  const out = { ...args };
  for (const k of Object.keys(args).filter(k => !props.includes(k))) {
    const free = props.filter(p => !(p in out));
    const req = free.filter(p => (a.required ?? []).includes(p));
    const pick = req.length === 1 ? req[0] : free.length === 1 ? free[0] : null;
    if (pick) { out[pick] = out[k]; delete out[k]; }
  }
  return out;
}

export function step(input, ctx) {
  switch (input.op) {
    case 'init': return init(input, ctx);
    case 'send': return send(input, ctx);
    case 'get': return out(ctx.state, false);
    case 'resume': return resume(input, ctx);
  }
  throw new Error(`notices: unknown op ${input.op}`);
}

export function onEvent(event, ctx) {
  const st = ctx.state ? { ...ctx.state, inflight: { ...ctx.state.inflight } } : null;
  if (st && event.payload && typeof event.payload.key === 'string') delete st.inflight[event.payload.key];
  return { ...out(st, false), state: st };
}

function out(st, sent) {
  return { output: { sent, busy: !!st && Object.keys(st.inflight ?? {}).length > 0 } };
}

function rowsOf(x) {
  if (Array.isArray(x)) return x;
  if (x && typeof x === 'object') {
    const arr = Object.values(x).find(v => Array.isArray(v));
    if (arr) return arr;
    return Object.entries(x).map(([k, v]) => ({ customerId: k, ...(typeof v === 'object' ? v : {}) }));
  }
  return [];
}

function emailOf(ctx, customerId) {
  const f = ctx.files ?? {};
  let c = f['master/customers.json'];
  if (typeof c === 'string') c = JSON.parse(c);
  const row = rowsOf(c).find(r => r && r.customerId === customerId);
  if (!row || typeof row.email !== 'string') throw new Error(`no email for customer ${customerId}`);
  return row.email;
}

function init(input, ctx) {
  if (ctx.state) return out(ctx.state, false);
  const st = { customerId: input.customerId, email: emailOf(ctx, input.customerId), sent: {}, inflight: {} };
  return { ...out(st, false), state: st };
}

function send(input, ctx) {
  const st = ctx.state;
  if (!st) throw new Error('notices.send before init');
  const key = input.template === 'cancel-refused' ? `cancel-refused.${input.occurrence}` : `${input.template}.${input.about}`;
  if (st.sent[key]) return { ...out(st, false) };          // exactly once
  const next = { ...st, sent: { ...st.sent, [key]: true }, inflight: { ...st.inflight, [key]: true } };
  const effect = {
    key, system: 'notify', op: 'send',
    args: fit('notify', 'send', { to: st.email, about: input.about, template: input.template, text: input.text ?? TEXT[input.template], ref: null }, ctx),
  };
  return { ...out(next, true), state: next, effects: [effect] };
}

function resume(input, ctx) {
  // §3.5: notices already on the migrated records count as sent.
  const r = input.records?.notices ?? {};
  const st = { customerId: input.customerId ?? r.customerId, email: r.email ?? emailOf(ctx, input.customerId), sent: {}, inflight: {} };
  for (const k of r.sent ?? []) st.sent[k] = true;
  return { ...out(st, false), state: st };
}
// Module cancellation, key: the order id. Owns R6.1 (cancel an order before any step committed), R6.2 (a customer
// cancel during processing: stop, compensate, cancel), R6.3 (a refused cancel: cancel-refused; an ended order changes
// nothing), R6.4 (a cancel before clearing counts), S4 and S7 (which carrier reports prove collection before the cancel),
// S6 (one collection ends the right to cancel the whole order). Calls fraud, order-progress, fulfilment, statuses and
// notices. Always returns `output`.

const COLLECTED = ['collected', 'inTransit', 'delivered'];
const DONE = ['completed', 'failed', 'cancelled'];

export function step(input, ctx) {
  switch (input.op) {
    case 'customer-cancel': return customerCancel(input, ctx);
    case 'cancel-order': return { output: { verdict: cancelOrder(input.at, input.reason, ctx) } };
  }
  throw new Error(`cancellation: unknown op ${input.op}`);
}

function customerCancel(input, ctx) {
  if (input.phase === 'ended') return { output: { verdict: 'nothing' } };        // R6.3, S15
  if (input.phase === 'not-cleared') {                                           // R6.4: counts
    ctx.call('fraud', ctx.key, { op: 'stop' });
    cancelOrder(input.at, 'customer', ctx);
    return { output: { verdict: 'counts' } };
  }
  // processing (R6.2, R6.3): judge on the reports that reached us before this cancel (S4, S7).
  const fs = ctx.call('statuses', ctx.key, { op: 'get' }).fulfilments;
  const cancelAt = Date.parse(input.at);
  let collected = false;
  for (const f of fs) {
    if (f.status === 'unavailable' || f.status === 'cancelled') continue;
    const r = ctx.call('fulfilment', f.fulfilmentId, { op: 'get' });
    for (const rep of r.reports ?? []) {
      if (COLLECTED.includes(rep.meaning) && Date.parse(rep.reportedAt) <= cancelAt) collected = true;
    }
  }
  if (collected) {
    ctx.call('notices', ctx.key, { op: 'send', template: 'cancel-refused', about: ctx.key, occurrence: input.eventId });
    return { output: { verdict: 'refused' } };
  }
  // Counted: stop the order, stop every open fulfilment (compensation runs there), cancel what is left.
  ctx.call('order-progress', ctx.key, { op: 'stop' });
  for (const f of fs) {
    if (DONE.includes(f.status) || f.status === 'unavailable') continue;
    ctx.call('fulfilment', f.fulfilmentId, { op: 'stop', at: input.at });
    ctx.call('statuses', ctx.key, { op: 'set', fulfilmentId: f.fulfilmentId, status: 'cancelled' });
  }
  ctx.call('statuses', ctx.key, { op: 'set', fulfilmentId: null, status: 'cancelled' });
  ctx.call('notices', ctx.key, { op: 'send', template: 'order-cancelled', about: ctx.key });
  return { output: { verdict: 'counts' } };
}

// R6.1: every fulfilment not completed, failed or cancelled becomes cancelled, then the order, then the notice.
// Used before any step committed (R2.1, R2.2, R3.2, R6.4). Returns 'done'.
function cancelOrder(at, reason, ctx) {
  const fs = ctx.call('statuses', ctx.key, { op: 'get' }).fulfilments;
  for (const f of fs) {
    if (DONE.includes(f.status)) continue;
    ctx.call('statuses', ctx.key, { op: 'set', fulfilmentId: f.fulfilmentId, status: 'cancelled' });
  }
  ctx.call('statuses', ctx.key, { op: 'set', fulfilmentId: null, status: 'cancelled' });
  ctx.call('notices', ctx.key, { op: 'send', template: 'order-cancelled', about: ctx.key });
  return 'done';
}

tool_use_result.stdout:
// Module fraud, key: the order id. Owns R2.1 (the verdict of fraud.check), R2.2 (the review task, its single deadline,
// the answers that count, the timeout) and S3 (one review deadline per order, from the first review task).
// Effects: fraud.check (key 'check'). Human tasks: fraudReview ('review-<n>'). Wake-up: 'deadline', after the
// deadline and never at it (an answer exactly at the deadline still counts). Always returns `output`.

const MIN = 60000;

function lastSunday(y, m) {
  const last = new Date(Date.UTC(y, m + 1, 0));
  return last.getUTCDate() - last.getUTCDay();
}

// Europe/Amsterdam offset in minutes at an instant (EU rule, switching at 01:00 UTC on the last Sundays of March and
// October).
function amsOffsetMin(ms) {
  const y = new Date(ms).getUTCFullYear();
  const start = Date.UTC(y, 2, lastSunday(y, 2), 1);
  const end = Date.UTC(y, 9, lastSunday(y, 9), 1);
